import{Bot,CreditCard,HelpCircle,LayoutDashboard,LogOut,Menu,MessageCircleMore,MessageSquareText,Search,Settings,ShieldCheck,Smartphone,WalletCards,Webhook,X}from"lucide-vue-next";
const{t,tr}=useAppPreferences(),route=useRoute(),mobileOpen=ref(false);const{data:authData}=await useFetch<any>("/api/auth/session");const user=computed(()=>authData.value?.user),isAdmin=computed(()=>["ADMIN","SUPER_ADMIN"].includes(user.value?.role));
